import React, { useState } from 'react';
import Layout from '../components/Layout';
import { Mail, Lock } from 'lucide-react';

const LoginPage = ({ onLogin, onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    const result = await onLogin(email, password);
    if (!result.success) setError('بيانات الدخول غير صحيحة');
  };

  return (
    <Layout onNavigate={onNavigate}>
      <div className="flex justify-center items-center py-20 px-4">
        <form
          onSubmit={handleSubmit}
          className="bg-white p-8 rounded-xl shadow-lg w-full max-w-md"
        >
          <h2 className="text-3xl font-bold text-[#0c1f40] mb-6 text-center">
            تسجيل الدخول
          </h2>

          {error && <p className="text-red-600 mb-4">{error}</p>}

          <div className="mb-4">
            <Mail className="inline ml-2 text-gray-400" />
            <input
              type="email"
              placeholder="البريد الإلكتروني"
              className="w-full border p-3 rounded"
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>

          <div className="mb-6">
            <Lock className="inline ml-2 text-gray-400" />
            <input
              type="password"
              placeholder="كلمة المرور"
              className="w-full border p-3 rounded"
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>

          <button className="w-full bg-[#0c1f40] text-white py-3 rounded font-bold">
            دخول
          </button>
        </form>
      </div>
    </Layout>
  );
};

export default LoginPage;
